-- The import publication-fence triggers of 0019, recreated in the form D1 parses. They behave as before.
DROP TRIGGER IF EXISTS form_import_epoch_flows_insert;
CREATE TRIGGER IF NOT EXISTS form_import_epoch_flows_insert BEFORE INSERT ON flows BEGIN SELECT RAISE(ABORT,'IMPORT_NATIVE_PUBLICATION_CHANGED') WHERE EXISTS(SELECT 1 FROM form_import_native_publication_fences WHERE target_id IN (SELECT NEW.id AS target_id)); UPDATE form_import_native_clock SET revision=revision+1 WHERE id=1 AND EXISTS(SELECT target_id FROM (SELECT NEW.id AS target_id) WHERE target_id IN (SELECT target_id FROM form_import_targets)); INSERT INTO form_import_native_epochs(target_id,revision) SELECT target_id,(SELECT revision FROM form_import_native_clock WHERE id=1) FROM (SELECT target_id FROM (SELECT NEW.id AS target_id) WHERE target_id IN (SELECT target_id FROM form_import_targets)) WHERE 1 ON CONFLICT(target_id) DO UPDATE SET revision=excluded.revision; END;
